code.source:
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> book;
    book["Asha"] = 91;
    book["Ravi"] = 78;
    book["Asha"] = 95;
    cout << book["Asha"] << endl;
    cout << book.size() << endl;
    return 0;
}

#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> book = {{"Ravi", 78}, {"Asha", 95}, {"Meera", 88}};
    for (const auto& [name, marks] : book) {
        cout << name << " " << marks << endl;
    }
    auto it = book.find("Meera");
    if (it != book.end()) {
        cout << "Found " << it->second << endl;
    }
    return 0;
}

